 const help=node('p'),capture=node('p'),note=node('p'),langHint=node('p'),toolbar=node('div'),controls=node('div'),selectionToolbar=node('div');toolbar.className=controls.className=selectionToolbar.className='toolbar';toolbar.append(source,fresh,picker);selectionToolbar.append(all,none);controls.append(prepare,start,resume,retry,pause,cancel,exportAll);help.className=capture.className=note.className=langHint.className='muted';host.append(help,toolbar,capture,form,summary,langHint,selectionToolbar,rows,controls,message,jobs,note);
