 picker.onchange=()=>act(async()=>{const projectId=get().id,file=picker.files[0];if(!file)return;if(file.size>4*1024**2)throw Error('Workflow limit: 4 MiB.');const raw=JSON.parse(await file.text());const inspected=await request('inspect',{source:raw});if(get().id!==projectId)return;const p=get();p.generation={...settings(),source:{prompt:raw.prompt||raw.output||raw,...(raw.workflow?{workflow:raw.workflow,widget_map:raw.widget_map||{}}:{})},output:inspected.output,runId:''};info=inspected;run=null;persist();refresh();});
