 async function originalImage(shot,file){const projectId=get().id;if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024**2)throw Error('Use PNG/JPEG/WebP, maximum 8 MiB.');const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file);});const img=new Image();img.src=data;await img.decode();if(img.naturalWidth*img.naturalHeight>60000000)throw Error('Maximum 60 megapixels.');if(get().id!==projectId||!get().shots.some(s=>s.id===shot.id))return;settings().images[shot.id]=data;changed();}
 function refreshRows(){rows.replaceChildren();const p=get(),s=settings();for(const[no,shot]of p.shots.entries()){const row=node('div');row.className='render-shot-row';const label=node('label'),check=node('input');check.type='checkbox';check.checked=s.selected.includes(shot.id);check.dataset.renderSelect=shot.id;check.onchange=()=>{s.selected=check.checked?[...new Set([...s.selected,shot.id])]:s.selected.filter(id=>id!==shot.id);persist();updateButtons();};label.className='lock';label.append(check,node('span',(no+1)+'. '+shot.title+' · '+(s.trial?Math.min(2,shot.duration):shot.duration)+' s'));row.append(label);const imagePick=node('input');imagePick.type='file';imagePick.accept='image/png,image/jpeg,image/webp';imagePick.hidden=true;imagePick.onchange=()=>act(()=>originalImage(shot,imagePick.files[0]));const imageButton=button(tr('renderSourceImage'),()=>imagePick.click()),hint=node('p',s.images[shot.id]?'✓ '+tr('renderSourceImage'):tr('renderWorkingImage'));hint.className='muted';const tools=node('div');tools.className='toolbar';tools.append(imageButton,imagePick,button(tr('renderExportOne'),()=>act(()=>exportFiles(shot.id))));if(s.images[shot.id])tools.append(button('×',()=>{delete s.images[shot.id];changed();}));const detail=node('details'),title=node('summary',tr('renderActualPrompt')),preview=node('pre');preview.className='render-prompt-preview';preview.textContent=selectedPrompt(shot);detail.append(title,preview);row.append(hint,tools,detail);rows.append(row);}updateButtons();}
