 const stateNames={HU:{ready:'Előkészítve',planned:'Várakozik',running:'Generálás',queued:'Sorban áll',complete:'Elkészült',failed:'Hiba',cancelled:'Megszakítva',unknown:'Ellenőrizendő',paused:'Szünetel',waiting:'Más ComfyUI-feladatra vár',submitting:'Átadás',cancelling:'Megszakítás folyamatban'},EN:{ready:'Prepared',planned:'Waiting',running:'Generating',queued:'Queued',complete:'Complete',failed:'Failed',cancelled:'Cancelled',unknown:'Needs review',paused:'Paused',waiting:'Waiting for other ComfyUI work',submitting:'Submitting',cancelling:'Stopping'}};
 function renderStatus(){monitor.update(run);if(!run){jobs.replaceChildren();lastJobs='';return;}const names=stateNames[get().language]||{},text=tr('renderState')+': '+(names[run.state]||run.state)+' · '+run.jobs.filter(j=>j.state==='complete').length+'/'+run.jobs.length;const signature=JSON.stringify([get().language,run.id,run.state,run.error,run.jobs.map(({prompt,...j})=>j)]);if(signature===lastJobs)return;lastJobs=signature;const old=new Map([...jobs.querySelectorAll('video')].map(v=>[v.dataset.key,v]));jobs.replaceChildren(node('h3',text));const locations=renderResultLocations(run);if(locations.folders.length>1){const hint=node('p',tr('renderSeveralFolders')+' · '+locations.folders.length);hint.className='hint';jobs.append(hint);}if(run.error)jobs.append(node('p',run.error));for(const j of run.jobs){const card=node('article');card.className='render-result';card.append(node('h4',j.number+'. '+j.title+' · '+(names[j.state]||j.state)),node('p',j.width+' × '+j.height+' · '+j.requested+' s → '+j.seconds.toFixed(3)+' s · '+j.frames+' frames / '+j.fps+' fps'));if(j.error){const error=node('p'),oom=j.errorInfo?.memory||/out.of.memory|CUDA_ERROR_OUT_OF_MEMORY/i.test(j.error),legacy=/^(?:[, .0-9\[\]\\nr]|…){60}/.test(j.error);error.className='hint render-error';error.textContent=(oom?tr('renderMemoryError'):legacy?tr('renderLegacyError'):j.error.slice(0,1200))+(j.errorInfo?.nodeType?' · '+j.errorInfo.nodeType+' #'+j.errorInfo.nodeId:'');card.append(error);if(j.errorInfo?.traceback){const details=node('details'),trace=node('pre',j.errorInfo.traceback);trace.className='render-prompt-preview';details.append(node('summary',tr('renderErrorDetails')),trace);card.append(details);}}if(locations.reusedShots.includes(j.shotId)){const reused=node('p',tr('renderReusedResult'));reused.className='hint';card.append(reused);}for(let i=0;i<j.results.length;i++){const key=run.id+j.shotId+i,v=old.get(key)||node('video');v.controls=true;v.preload='metadata';v.dataset.key=key;if(!old.has(key))v.src='/api/render/media?'+new URLSearchParams({id:run.id,shot:j.shotId,index:i});card.append(v);const saved=j.results[i],location=node('p',tr('renderSavedLocation')+': ' +[saved.subfolder,saved.filename].filter(Boolean).join('/')),link=node('a',tr('renderDownloadVideo'));location.className='muted';location.style.overflowWrap='anywhere';link.href=v.src;link.download=saved.filename;card.append(location,link);}card.append(button(tr('renderExportOne'),()=>act(()=>exportFiles(j.shotId))));jobs.append(card);}updateButtons();}
 function updateButtons(){const active=!!(run?.autoRun||run?.jobs.some(j=>['submitting','queued','running','cancelling'].includes(j.state)));prepare.disabled=busy||active||!settings().source||!settings().selected.length;start.disabled=busy||active||!run?.jobs.some(j=>j.state==='planned');resume.disabled=busy||active||!run?.jobs.some(j=>j.state==='planned'||['queued','running','submitting','cancelling'].includes(j.state));retry.disabled=busy||active||!run?.jobs.some(j=>['failed','cancelled','unknown'].includes(j.state));pause.disabled=cancel.disabled=busy||!active;exportAll.disabled=busy||!run;for(const el of [source,fresh,address,width,height,mode,promptMode,output,all,none,follow])el.disabled=busy||active;}
